# ---- 京都 ----
s("京都駅ビル","post",1997,"京都市下京区","原広司","吹き抜けの大空間をもつ駅ビル","古都の玄関口にできた巨大な駅ビル。ガラスと鉄骨の大屋根の下に、長い大階段が続く。建設時には景観をめぐって議論になった。",34.9858,135.7588)
s("京都タワー","tower",1964,"京都市下京区","山田守","高さ131mの白い灯台型の塔","鉄骨の骨組みを使わず、鋼板を円筒に溶接した構造の塔。ビルの上に立つ珍しい形で、京都の街なかで高さを持つランドマークになっている。",34.9875,135.7594)
s("東寺 五重塔","tower",1644,"京都市南区","","高さ約55m、日本一高い木造の塔","平安京の入口を守った東寺の塔。江戸時代の再建で、木造の塔としては日本で最も高い。心柱が地震の揺れを吸収する仕組みで知られる。",34.9805,135.7477,"国宝")
s("法観寺 八坂の塔","tower",1440,"京都市東山区","","東山の町並みに立つ五重塔","清水寺に向かう坂の途中で、町並みの上に突き出して見える塔。何度も焼けたが、そのたびに再建されてきた。",34.9985,135.7807,"重文")
s("清水寺 本堂（清水の舞台）","tower",1633,"京都市東山区","","断崖に張り出した懸造の舞台","約140本の柱を、釘を使わず組んだ懸造で、崖から大きく張り出している。木造の格子が、斜面に建つ建築を安定させている。",34.9949,135.7850,"国宝")
s("三十三間堂","tower",1266,"京都市東山区","","南北約120mの細長い本堂","柱の間が33あることから名がついた。長さ約120mは木造建築として国内最長級。堂の中に1001体の観音像が並ぶ。",34.9879,135.7716,"国宝")
s("知恩院 三門","tower",1621,"京都市東山区","","高さ約24m、木造の三門としては国内最大級","二層の大きな門で、構えの大きさに圧倒される。楼上に上がることもできる。",35.0053,135.7819,"国宝")
s("南禅寺 三門","tower",1628,"京都市左京区","藤堂高虎","石川五右衛門の伝説で知られる門","大きな二重門で、五右衛門が「絶景かな」と言ったとされる。山の斜面に石垣と階段が築かれている。",35.0111,135.7933,"重文")
s("東本願寺 御影堂","tower",1895,"京都市下京区","","世界最大級の木造建築のひとつ","幅約76m、高さ約38mの大きな建物。明治時代の再建で、巨大な木材を運ぶ際には、髪の毛を編んだ綱「毛綱」が使われたことが知られる。",34.9915,135.7587,"重文")
s("京都御所 紫宸殿","tower",1855,"京都市上京区","","檜皮葺の寝殿造の正殿","天皇の即位礼などを行った正殿。平安時代の宮殿の形式を、江戸時代の再建で伝えている。",35.0254,135.7620)
s("二条城 二の丸御殿","tower",1626,"京都市中京区","","武家書院造の代表","徳川将軍の京都の宿所で、大政奉還が行われた場所。廊下の床板が、歩くと鳴る「うぐいす張り」で知られる。",35.0142,135.7480,"国宝")
s("金閣寺 舎利殿","tower",1955,"京都市北区","","金箔を張った三層の楼閣","1950年に放火で焼け、1955年に再建された。3層それぞれに異なる様式を使う。",35.0394,135.7292,"世界遺産")
s("銀閣寺 観音殿","tower",1489,"京都市左京区","","簡素で落ち着いた二層の楼閣","東山文化を代表する建物。外壁に銀箔は張られておらず、簡素な美しさに特徴がある。",35.0270,135.7982,"国宝")
s("平等院 鳳凰堂","tower",1053,"宇治市","","極楽浄土を表現した阿弥陀堂","池に浮かぶように建つ。鳥が翼を広げたような形をしていて、十円硬貨の裏の図柄としても知られる。",34.8893,135.8077,"国宝")
s("醍醐寺 五重塔","tower",951,"京都市伏見区","","京都府で最古の木造の塔","平安時代に建てられた五重塔で、塔の屋根が大きくて軽やかに見える。内部の壁画も見どころ。",34.9520,135.8180,"国宝")
s("仁和寺 五重塔","tower",1644,"京都市右京区","","江戸時代の寛永年間の五重塔","塔の各層の軒の出が大きく、均整がとれている。仁王門や金堂と並ぶ境内の中心的な建物。",35.0314,135.7140,"重文")
s("旧京都府庁舎（旧本館）","modern",1904,"京都市上京区","松室重光","現役で使われる最古級の庁舎","ルネサンス風の洋館で、京都府の庁舎として100年以上使われている。中庭を囲んで建つ。",35.0211,135.7587,"重文")
s("京都市役所本庁舎","modern",1927,"京都市中京区","武田五一","和洋折衷の意匠をもつ庁舎","御池通に面して建つ。大きな時計塔と、和風と洋風が混じる装飾が特徴で、近年は耐震工事と増築を行った。",35.0113,135.7681)
s("京都文化博物館 別館（旧日本銀行京都支店）","modern",1906,"京都市中京区","辰野金吾・長野宇平治","赤れんがと白い石の帯をもつ洋館","辰野金吾が設計した旧日本銀行京都支店。赤れんがの壁に白い石の帯が入る、辰野式と呼ばれる意匠。",35.0083,135.7655,"重文")
s("中京郵便局（旧局舎）","modern",1902,"京都市中京区","吉井茂則","れんが造の旧郵便局","れんが造の外壁を残して、中を現代の郵便局に使っている。",35.0089,135.7566)
s("京都国立博物館（明治古都館）","modern",1895,"京都市東山区","片山東熊","フランス風ルネサンス様式の博物館","赤坂離宮と同じ片山東熊が設計した。れんが造の建物で、現在は展示ではなく特別公開などで使われる。",34.9896,135.7733,"重文")
s("京都国立近代美術館","post",1986,"京都市左京区","槇文彦","格子状の外壁をもつ美術館","槇文彦が設計した。白い格子状の壁が岡崎の景観に溶け込み、平安神宮の大鳥居を借景にしている。",35.0126,135.7845)
s("京都市京セラ美術館","modern",1933,"京都市左京区","前田健二郎","和洋折衷の帝冠様式の美術館","日本初の公立美術館のひとつ。瓦屋根を載せた洋風建築で、2020年にリニューアルして地下に新館を設けた。",35.0125,135.7826,"")
s("ロームシアター京都","post",1960,"京都市左京区","前川國男","打放しコンクリートの文化施設","前川國男が設計した旧京都会館で、2016年に改修された。ロビーの大きな階段と、岡崎の街並みに調和する外観が特徴。",35.0122,135.7817)
s("京都府立図書館（旧館）","modern",1909,"京都市左京区","","岡崎に建つ洋風の図書館","岡崎公園の一角にあり、明治末期の洋風建築のデザインを伝える。",35.0120,135.7840)
s("琵琶湖疏水 南禅寺水路閣","water",1888,"京都市左京区","田邉朔郎","古代ローマ風のれんがアーチの水路橋","琵琶湖から京都へ水を引く疏水の水路橋。れんがのアーチが南禅寺の境内を横切り、今も水が流れている。",35.0113,135.7940,"")
s("蹴上インクライン","rail",1891,"京都市東山区","田邉朔郎","舟を台車に載せて坂を上げ下げした傾斜鉄道","琵琶湖疏水の水位の差を、船を台車に載せて越えるための傾斜鉄道。長さは約582mで、線路は今も残っている。",35.0120,135.7883)
s("蹴上発電所","water",1891,"京都市東山区","田邉朔郎","日本初の事業用水力発電所のひとつ","琵琶湖疏水の水を使った水力発電所。京都にはこの電力で日本初の電車が走った。",35.0105,135.7895)
s("蹴上浄水場","water",1912,"京都市東山区","","疏水の水をきれいにする浄水場","琵琶湖疏水の水を市内に送り出すための浄水場。ツツジの季節には一般公開される。",35.0096,135.7918)
s("三条大橋","bridge",1950,"京都市中京区・東山区","京都市","東海道五十三次の終点の橋","鴨川に架かる、東海道の終点にあたる橋。擬宝珠の一部に、秀吉時代の古い橋のものが使われている。",35.0094,135.7728)
s("四条大橋","bridge",1935,"京都市中京区・東山区","京都市","鴨川に架かる四条通の橋","祇園と河原町をつなぐ橋。現在の橋は昭和10年のもので、橋の上から鴨川と東山が一望できる。",35.0038,135.7706)
s("五条大橋","bridge",1959,"京都市下京区・東山区","京都市","弁慶と牛若丸の舞台の橋","現在の橋は1959年に架けられた。擬宝珠は古い橋のものを使っている。",34.9968,135.7694)
s("七条大橋","bridge",1913,"京都市下京区・東山区","京都市","鴨川に架かる最古級のコンクリート橋","昭和初期に鉄筋コンクリートが使われ始めた頃の橋で、京都駅から東山を結ぶ重要な橋。",34.9910,135.7685)
s("丸太町橋","bridge",1913,"京都市上京区・左京区","京都市","鴨川に架かる丸太町通の橋","大正初期のアーチ橋で、鴨川沿いの景観を形づくる橋のひとつ。",35.0165,135.7722)
s("賀茂大橋","bridge",1925,"京都市上京区・左京区","京都市","出町柳の鴨川にかかる橋","鴨川と高野川の合流点に近い橋。この橋から、鴨川デルタを見渡せる。",35.0285,135.7715)
s("京都鉄道博物館 扇形車庫","rail",1914,"京都市下京区","国鉄","半円形に蒸気機関車が並ぶ車庫","蒸気機関車が方向を変えるための転車台を囲む、扇形の車庫。今は鉄道博物館として使われている。",34.9877,135.7440,"重文")
s("南座","modern",1929,"京都市東山区","白井晟一ほか","歌舞伎の殿堂","祇園の四条大橋のたもとに建つ劇場。桃山風の屋根の下で、歌舞伎の興行が行われる。",35.0040,135.7740)
s("同志社 彰栄館","modern",1884,"京都市上京区","ハンセル","赤れんがの洋風校舎","同志社大学の最初のれんが造の校舎で、新島襄の指揮で建てられた。現存する日本最古級の煉瓦造の学舎。",35.0305,135.7600,"重文")
s("同志社 クラーク記念館","modern",1893,"京都市上京区","ハンセル","ゴシック様式のれんが建築","同志社のれんがの建物のひとつで、ゴシック風の塔や窓が特徴。",35.0300,135.7595,"重文")
s("京都大学 時計台記念館","modern",1925,"京都市左京区","武田五一","大学のシンボルになった時計台","大学の正門から見える大きな時計台。コンクリートの建築で、中に国際会議場が設けられている。",35.0262,135.7808)
s("京都コンサートホール","post",1995,"京都市左京区","磯崎新","京都府立植物園のそばに建つホール","大ホールは、シューボックス型で音響に優れる。磯崎新らしい幾何学的なデザイン。",35.0455,135.7600)
s("京都国際会館","post",1966,"京都市左京区","大谷幸夫","宝ヶ池のほとりの国際会議場","合掌造りを思わせる逆台形の大きな建物。日本で初めての国際会議場として開館した。",35.0605,135.7860)
s("渡月橋","bridge",1934,"京都市右京区","京都府","嵐山の桂川に架かる木造風の橋","昭和9年に架けられた橋。桁は鉄筋コンクリートでできているが、欄干などが木造に見えるように仕上げられている。",35.0094,135.6779)
s("嵯峨野トロッコ 第一保津川橋梁","rail",1899,"京都市右京区","","保津川の渓谷を渡る鉄橋","旧山陰線の鉄橋を、観光列車が走っている。渓谷の紅葉の中を渡ると、景色が大きく変わる。",35.0330,135.6190)
s("宇治橋","bridge",1996,"宇治市","","日本三古橋のひとつ","奈良時代以前から続く橋。現在の橋は1996年に架け替えられた木造風の橋で、宇治川の中ほどで水を引き込む構造がある。",34.8905,135.8070)
s("天ヶ瀬ダム","water",1964,"宇治市","建設省","宇治川の洪水を調節するアーチダム","琵琶湖から流れ出る瀬田川のすぐ下流に築かれたアーチ式のダム。景観に配慮したデザインが評価されている。",34.8845,135.8245)
s("舞鶴 赤れんが倉庫群","port",1901,"舞鶴市","旧海軍","旧海軍の兵器庫として建てられたれんが倉庫","舞鶴の港に並ぶ赤れんがの倉庫群。今は博物館や市のイベント施設として使われている。",35.4750,135.3860,"重文")
